CREATE   VIEW [synapse_fo].[vwPROCPROCUREMENTPRODUCTCATEGORYENTITY]
AS
SELECT T1.NAME AS CATEGORYNAME
	,T1.RECID AS CATEGORYRECORDID
	,T1.MODIFIEDDATETIME AS MODIFIEDDATETIME
	,T1.MODIFIEDBY AS MODIFIEDBY
	,T1.CREATEDDATETIME AS CREATEDDATETIME
	,T1.CREATEDBY AS CREATEDBY
	,T1.RECVERSION AS RECVERSION
	,T1.PARTITION AS PARTITION
	,T1.RECID AS RECID
	,T2.RECVERSION AS RECVERSION#2
	,T2.PARTITION AS PARTITION#2
	,T2.RECID AS RECID#2
	,T3.RECVERSION AS RECVERSION#3
	,T3.PARTITION AS PARTITION#3
	,T3.RECID AS RECID#3
FROM synapse_fo.ECORESCATEGORY T1
CROSS JOIN synapse_fo.ECORESCATEGORYHIERARCHY T2
CROSS JOIN synapse_fo.ECORESCATEGORYHIERARCHYROLE T3
WHERE (
		(
			(T1.CATEGORYHIERARCHY = T2.RECID)
			AND (T1.PARTITION = T2.PARTITION)
			)
		AND (
			(T3.NAMEDCATEGORYHIERARCHYROLE = 1)
			AND (
				(T2.RECID = T3.CATEGORYHIERARCHY)
				AND (T2.PARTITION = T3.PARTITION)
				)
			)
		)
